-- Run against zptjziewsfuvfcogrikz after indai-jobs has been deployed.
-- The scheduler token is generated by the migration and stays inside Vault.
do $target$
declare
  target constant text := 'https://zptjziewsfuvfcogrikz.supabase.co';
  current_url text;
begin
  select decrypted_secret into current_url from vault.decrypted_secrets where name='indai_project_url';
  if not found then
    perform vault.create_secret(target,'indai_project_url');
  elsif rtrim(current_url,'/') <> target then
    raise exception 'An existing scheduler URL points to a different project';
  end if;
end $target$;
